#!/usr/bin/env python3
"""Diagnose why g_page_item_ctr stopped after 2026-10-23 on test."""
import json
import urllib.request
from pathlib import Path

TOKEN = [ln.split("=", 1)[1].strip() for ln in Path("/Users/mac/.dc-platform/config/test-platform.env").read_text().splitlines() if ln.startswith("DC_USER_TOKEN=")][0]
BASE = "http://127.0.0.1:18012"
H = {"Authorization": f"Bearer {TOKEN}"}


def get(path: str):
    req = urllib.request.Request(BASE + path, headers=H)
    with urllib.request.urlopen(req, timeout=90) as resp:
        return json.loads(resp.read(), strict=False)


def post(path: str, body: dict):
    req = urllib.request.Request(
        BASE + path,
        data=json.dumps(body).encode(),
        headers={**H, "Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=90) as resp:
        return json.loads(resp.read(), strict=False)


print("=== daemon test ===")
try:
    print(json.dumps(get("/api/v1/runner/daemon?env=test"), ensure_ascii=False, indent=2)[:2500])
except Exception as e:
    print("err", e)

print("\n=== step-results ===")
# try shapes from runner-client
from typing import Any

candidates = [
    ("POST", "/api/v1/runner/step-results", {"env": "test", "steps": ["ads_page_item_ctr_d"], "dates": ["2026-10-23", "2026-10-24", "2026-10-25", "2026-10-26"]}),
    ("POST", "/api/v1/runner/step-results", {"env": "test", "step": "ads_page_item_ctr_d", "from": "2026-10-20", "to": "2026-10-27"}),
    ("POST", "/api/v1/runner/step-results", {"env": "test", "names": ["ads_page_item_ctr_d", "dim_app_page_item_d"], "dt": "2026-10-23"}),
]
for method, path, body in candidates:
    try:
        if method == "POST":
            r = post(path, body)
        else:
            r = get(path)
        print("OK", path, body)
        print(json.dumps(r, ensure_ascii=False, indent=2, default=str)[:3000])
        break
    except Exception as e:
        print("fail", body, "->", e)

print("\n=== recent rerun list (test) ===")
try:
    runs = get("/api/v1/runner/rerun/runs?env=test")
    for r in (runs.get("runs") or [])[:8]:
        print({k: r.get(k) for k in ("run_id", "state", "by", "done", "total", "started_at", "finished_at")})
        print("  args", r.get("args"))
except Exception as e:
    print(e)

