def _prod_tables_missing(fqns: list[str]) -> tuple[list[str], dict[str, str]]:
    """查 prod SR information_schema：返回 (missing_fqns, db_errors)。

    与 refresh-prod-built 同源（DC_SR_CNF + mysql CLI）。查库失败记入 db_errors，
    该库下的 fqn 一律视为不可确认（由调用方当硬错拦）。
    """
    import os
    import subprocess

    by_db: dict[str, list[str]] = {}
    for fqn in fqns:
        parts = fqn.split(".", 1)
        if len(parts) != 2 or not parts[0] or not parts[1]:
            continue
        db, tbl = parts[0].strip(), parts[1].strip()
        by_db.setdefault(db, []).append(tbl)

    sr_cnf = os.environ.get("DC_SR_CNF", "/data/dcpaltform/monitor/sr.cnf")
    existing: dict[str, set[str]] = {}
    db_errors: dict[str, str] = {}
    for db in by_db:
        sql = f"SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='{db}'"
        try:
            r = subprocess.run(
                ["mysql", f"--defaults-file={sr_cnf}", "-BN", "-e", sql],
                capture_output=True,
                text=True,
                timeout=30,
            )
            if r.returncode != 0:
                db_errors[db] = f"mysql err: {r.stderr.strip()[:200]}"
                continue
            existing[db] = {ln.strip() for ln in r.stdout.splitlines() if ln.strip()}
        except subprocess.TimeoutExpired:
            db_errors[db] = "timeout 30s"
        except Exception as e:  # noqa: BLE001
            db_errors[db] = f"exception: {e}"

    missing: list[str] = []
    for db, tbls in by_db.items():
        if db in db_errors:
            continue
        have = existing.get(db) or set()
        for tbl in tbls:
            if tbl not in have:
                missing.append(f"{db}.{tbl}")
    return missing, db_errors


