def _sr_fqns_only(fqns: list[str]) -> list[str]:
    out: list[str] = []
    for fqn in fqns:
        db = fqn.split(".", 1)[0].strip().lower()
        if db in _SR_SCHEMA_ALLOW:
            out.append(fqn)
    return out


def _stage_status_value(stage_status: dict, stage: int) -> str:
    v = stage_status.get(str(stage))
    if v is None:
        v = stage_status.get(stage)
    if isinstance(v, dict):
        v = v.get("status") or v.get("state") or ""
    return str(v or "").strip().lower()


def _assert_prod_complete_hard_gates(
    idx_row: DevSessionIndex,
    *,
    fqns: list[str],
    tasks: list,
    spark_steps: list[str],
) -> list[str]:
    """完成发布前硬闸。返回阻塞原因列表；空列表=放行。

    任一条不达标 → 调用方 409，禁止写 PublishRun / 归档。
    """
    blocks: list[str] = []
    state = dict(idx_row.state_json or {})
    stage_status = dict(getattr(idx_row, "stage_status", None) or state.get("stage_status") or {})

    # —— 1) stage 1–6 必须 done（空标 / 跳步不许完成发布）——
    for i in range(1, 7):
        v = _stage_status_value(stage_status, i)
        if v != "done":
            blocks.append(f"stage {i} 未 done（当前={v or '空'}）")

    # —— 2) SR 产出表必须在 prod 真实存在 ——
    outs = state.get("outputs") or []
    all_fqns = list(fqns)
    if not all_fqns:
        for o in outs:
            if not isinstance(o, dict):
                continue
            layer = str(o.get("layer") or "").strip()
            tbl = str(o.get("table_name") or "").strip()
            if layer and tbl:
                all_fqns.append(f"{layer}.{tbl}")
    sr_fqns = _sr_fqns_only(all_fqns)
    if sr_fqns:
        missing, db_errs = _prod_tables_missing(sr_fqns)
        if db_errs:
            blocks.append(f"查 prod SR 失败：{db_errs}")
        if missing:
            blocks.append(f"prod 未建表：{', '.join(missing)}")
    # outputs 上已写 false 的也拦（与 refresh-prod-built 一致）
    for o in outs:
        if not isinstance(o, dict):
            continue
        layer = str(o.get("layer") or "").strip()
        tbl = str(o.get("table_name") or "").strip()
        if not layer or not tbl or layer.lower() not in _SR_SCHEMA_ALLOW:
            continue
        if o.get("prod_table_built") is False:
            fqn = f"{layer}.{tbl}"
            if fqn not in (missing if sr_fqns else []):  # noqa: F821 — missing 可能未定义
                pass
            # 上面 SR 查已覆盖；此处补：state 明确 false 且未进 sr_fqns 时
            if fqn not in sr_fqns and o.get("prod_table_built") is False:
                blocks.append(f"outputs 标记 prod 未建表：{fqn}")

    engine = str(getattr(idx_row, "engine", None) or state.get("engine") or "dolphin").strip().lower()
    if engine not in ("dolphin", "spark"):
        engine = "dolphin"

    # —— 3) spark：必须有步且（编排存在性由调用方后续再查）——
    if engine == "spark":
        if not spark_steps:
            blocks.append("spark 会话必须传 spark_steps（且步须已挂进 prod 编排）")
        return blocks

    # —— 4) dolphin：task 同步 + prod 实查 ONLINE/flag/schedule ——
    valid_tasks = []
    for t in tasks or []:
        if not isinstance(t, dict):
            continue
        wf = int(t.get("wf_code") or 0)
        task_code = int(t.get("task_code") or 0)
        proj = int(t.get("project_code") or 0)
        name = str(t.get("task_name") or "").strip()
        if wf and task_code:
            valid_tasks.append(
                {"wf_code": wf, "task_code": task_code, "project_code": proj, "task_name": name}
            )

    if not valid_tasks:
        blocks.append("海豚会话 body.tasks 为空或缺 wf/task code（须先 Step2 同步到 prod）")
        return blocks

    # owned[test] 须全部覆盖
    owned = state.get("dolphin_owned_tasks") or []
    expected_names = {
        str(o.get("task_name") or "").strip()
        for o in owned
        if isinstance(o, dict)
        and str(o.get("task_name") or "").strip()
        and str(o.get("env") or "test").lower() == "test"
    }
    got_names = {t["task_name"] for t in valid_tasks if t["task_name"]}
    if expected_names:
        not_synced = sorted(expected_names - got_names)
        if not_synced:
            blocks.append(f"尚有 test owned task 未进本次发布：{', '.join(not_synced)}")

    # prod 海豚实查
    try:
        with DolphinClient("prod") as ds:
            # 按 wf 缓存
            wf_cache: dict[tuple[int, int], dict] = {}
            for t in valid_tasks:
                proj, wf, task_code, name = (
                    t["project_code"],
                    t["wf_code"],
                    t["task_code"],
                    t["task_name"],
                )
                if not proj:
                    blocks.append(f"task `{name or task_code}` 缺 project_code")
                    continue
                key = (proj, wf)
                if key not in wf_cache:
                    try:
                        wf_cache[key] = ds.get_workflow(proj, wf)
                    except Exception as e:  # noqa: BLE001
                        blocks.append(f"读 prod wf project={proj} wf={wf} 失败：{e}")
                        wf_cache[key] = {}
                        continue
                detail = wf_cache[key] or {}
                if not detail:
                    continue
                rel = str(detail.get("release_state") or "").upper()
                if rel != "ONLINE":
                    blocks.append(
                        f"prod wf `{detail.get('name') or wf}` release_state={rel or '空'}（须 ONLINE）"
                    )
                matched = next(
                    (
                        x
                        for x in (detail.get("tasks") or [])
                        if int(x.get("code") or 0) == task_code
                        or (name and str(x.get("name") or "") == name)
                    ),
                    None,
                )
                if not matched:
                    blocks.append(
                        f"prod wf 里找不到 task `{name or task_code}`（code={task_code}）"
                    )
                else:
                    flag = str(matched.get("flag") or "").upper()
                    if flag == "NO":
                        blocks.append(f"prod task `{matched.get('name')}` flag=NO（已废弃，禁止发布）")
                # schedule 至少一条 ONLINE
                try:
                    scheds = ds.list_schedules(proj, wf) or []
                except Exception as e:  # noqa: BLE001
                    blocks.append(f"读 prod schedule project={proj} wf={wf} 失败：{e}")
                    continue
                online_sched = [
                    s
                    for s in scheds
                    if str(s.get("releaseState") or s.get("release_state") or "").upper()
                    == "ONLINE"
                ]
                if not online_sched:
                    blocks.append(
                        f"prod wf `{detail.get('name') or wf}` 无 ONLINE 的 schedule（定时不会跑）"
                    )
    except Exception as e:  # noqa: BLE001
        blocks.append(f"连 prod 海豚失败，无法验收 task/ONLINE/schedule：{e}")

    return blocks

